 83	/// Assemble a [`PreparedConverse`] from the builder `Config` and a [`ModelRequest`].
 84	///
 85	/// # Errors
 86	/// - Reserved tool name (`__paigasus_structured_output__` used by the caller).
 87	/// - `ResponseFormat::JsonSchema`/`JsonObject` combined with `ToolChoice::Tool` (conflict).
 88	/// - `ResponseFormat::JsonSchema`/`JsonObject` combined with `ToolChoice::None` (conflict).
 89	/// - No message with content after empty/whitespace-only text is dropped.
 90	/// - The last user message had only empty/whitespace-only text and the request would end with an assistant message.
 91	pub(crate) fn build_request(
 92	    cfg: &Config,
 93	    req: &ModelRequest,
 94	) -> Result<PreparedConverse, ModelError> {
 95	    let family = cfg.family;
 96	    let ruleset = Ruleset::for_family(family);
 97	
 98	    // Guard: ResponseFormat::JsonSchema / JsonObject + ToolChoice::Tool → conflict.
 99	    let synthesizing_rf = matches!(
100	        req.model_settings.response_format.as_ref(),
101	        Some(paigasus_helikon_core::ResponseFormat::JsonSchema { .. })
102	            | Some(paigasus_helikon_core::ResponseFormat::JsonObject),
103	    );
104	    let forced_tool = matches!(
105	        req.model_settings.tool_choice.as_ref(),
106	        Some(ToolChoice::Tool { .. }),
107	    );
108	    if synthesizing_rf && family.supports_forced_tool_choice() && forced_tool {
109	        return Err(ModelError::Other(anyhow::anyhow!(
110	            "ResponseFormat::JsonSchema/JsonObject and ToolChoice::Tool are mutually \
111	             exclusive on Bedrock — use one or the other",
112	        )));
113	    }
114	
115	    // Guard: ResponseFormat::JsonSchema / JsonObject + ToolChoice::None → conflict.
116	    // Synthesis requires injecting a tool; ToolChoice::None suppresses toolConfig entirely.
117	    let none_choice = matches!(
118	        req.model_settings.tool_choice.as_ref(),
119	        Some(ToolChoice::None),
120	    );
121	    if synthesizing_rf && family.supports_forced_tool_choice() && none_choice {
122	        return Err(ModelError::Other(anyhow::anyhow!(
123	            "ResponseFormat::JsonSchema/JsonObject and ToolChoice::None are mutually \
124	             exclusive on Bedrock — structured-output synthesis requires a tool call",
125	        )));
126	    }
127	
128	    // ToolChoice::None means the model MUST NOT call any tool this turn.
129	    // Omit toolConfig entirely (do not send user tools either).
130	    if none_choice {
131	        let translated = items_to_messages(&req.messages)?;
132	        let inference_config = build_inference_config(req, cfg);
133	        return Ok(PreparedConverse {
134	            model_id: cfg.model_id.clone(),
135	            system: translated.system,
136	            messages: translated.messages,
137	            tool_config: None,
138	            inference_config,
139	            synthesizing: false,
140	        });
141	    }
142	
143	    // Translate messages.
144	    let translated = items_to_messages(&req.messages)?;
145	
146	    // Translate user tool defs (also validates reserved name).
147	    let user_specs = tool_specs(&req.tools, ruleset)?;
148	
149	    // Synthesize structured output tool (if applicable).
150	    let Synthesized {
151	        tool: synth_tool,
152	        tool_choice: synth_tc,
153	        synthesizing,
154	    } = synthesize(req.model_settings.response_format.as_ref(), family, ruleset)?;
155	
156	    // Merge tool lists: user tools first, synthesized appended.
157	    let mut all_tools: Vec<Tool> = user_specs.into_iter().map(Tool::ToolSpec).collect();
158	    if let Some(st) = synth_tool {
159	        all_tools.push(Tool::ToolSpec(st));
160	    }
161	
162	    // Build ToolConfiguration (only when there are tools or a tool_choice).
163	    let caller_tc = req
164	        .model_settings
165	        .tool_choice
166	        .as_ref()
167	        .and_then(|tc| translate_tool_choice(tc, family));
168	
169	    // Synthesis overrides caller tool_choice.
170	    // synth_tool.is_some() always pushes to all_tools above, so a synthesized tool_choice is never silently dropped here.
171	    let effective_tc = synth_tc.or(caller_tc);
172	
173	    // Validate forced tool choices on supported families.
174	    // (On unsupported families, forced choices were already omitted by translate_tool_choice.)
175	    if family.supports_forced_tool_choice() {
176	        match req.model_settings.tool_choice.as_ref() {
177	            Some(ToolChoice::Required) if !synthesizing => {
178	                if all_tools.is_empty() {
179	                    return Err(ModelError::Other(anyhow::anyhow!(
180	                        "ToolChoice::Required requires at least one tool to be defined",
181	                    )));
182	                }
183	            }
184	            Some(ToolChoice::Tool { name }) => {
185	                let tool_names: Vec<&str> = all_tools
186	                    .iter()
187	                    .filter_map(|t| {
188	                        if let Tool::ToolSpec(spec) = t {
189	                            Some(spec.name())
190	                        } else {
191	                            None
192	                        }
193	                    })
194	                    .collect();
195	                if !tool_names.contains(&name.as_str()) {
196	                    return Err(ModelError::Other(anyhow::anyhow!(
197	                        "ToolChoice::Tool references tool {:?} which is not defined in the tool list",
198	                        name,
199	                    )));
200	                }
201	            }
202	            _ => {}
203	        }
204	    }
205	
206	    let tool_config = if !all_tools.is_empty() {
207	        let mut builder = ToolConfiguration::builder();
208	        for t in all_tools {
209	            builder = builder.tools(t);
210	        }
211	        if let Some(tc) = effective_tc {
212	            builder = builder.tool_choice(tc);
213	        }
214	        Some(builder.build().map_err(|e| {
215	            ModelError::Other(anyhow::anyhow!("failed to build ToolConfiguration: {e}"))
216	        })?)
217	    } else if effective_tc.is_some() {
218	        // ToolConfiguration requires at least one tool — skip tool_choice when
219	        // no tools are present to avoid a build error.
220	        tracing::debug!(
221	            target: "paigasus::bedrock::translate",
222	            "tool_choice requested but no tools provided; omitting ToolConfiguration",
223	        );
224	        None
225	    } else {
226	        None
227	    };
228	
229	    // Build InferenceConfiguration.
230	    let inference_config = build_inference_config(req, cfg);
231	
232	    Ok(PreparedConverse {
233	        model_id: cfg.model_id.clone(),
234	        system: translated.system,
235	        messages: translated.messages,
236	        tool_config,
237	        inference_config,
238	        synthesizing,
239	    })
240	}
