297	// ── Wire-projection (snapshot tests) ─────────────────────────────────────────
298	
299	/// Project a [`PreparedConverse`] into a stable [`serde_json::Value`] for
300	/// snapshot tests.
301	///
302	/// This projection is deliberately **not** based on `Debug` output of the SDK
303	/// types, which can change across SDK version bumps. Instead, it is a hand-written
304	/// extraction of the semantically relevant fields.
305	#[cfg(test)]
306	pub(crate) fn to_wire_json(p: &PreparedConverse) -> serde_json::Value {
307	    use aws_sdk_bedrockruntime::types::{
308	        ContentBlock, SystemContentBlock, ToolChoice as SdkToolChoice, ToolResultContentBlock,
309	    };
310	    use serde_json::{json, Value};
311	
312	    // System blocks
313	    let system: Vec<Value> = p
314	        .system
315	        .iter()
316	        .map(|s| match s {
317	            SystemContentBlock::Text(t) => json!({"text": t}),
318	            _ => json!({"unknown": true}),
319	        })
320	        .collect();
321	
322	    // Messages
323	    let messages: Vec<Value> = p
324	        .messages
325	        .iter()
326	        .map(|m| {
327	            let role = match m.role {
328	                aws_sdk_bedrockruntime::types::ConversationRole::User => "user",
329	                aws_sdk_bedrockruntime::types::ConversationRole::Assistant => "assistant",
330	                _ => "unknown",
331	            };
332	            let content: Vec<Value> = m
333	                .content
334	                .iter()
335	                .map(|b| match b {
336	                    ContentBlock::Text(t) => json!({"text": t}),
337	                    ContentBlock::ToolUse(tu) => json!({
338	                        "toolUse": {
339	                            "toolUseId": tu.tool_use_id,
340	                            "name": tu.name,
341	                        }
342	                    }),
343	                    ContentBlock::ToolResult(tr) => {
344	                        let text_content = tr
345	                            .content
346	                            .iter()
347	                            .find_map(|c| {
348	                                if let ToolResultContentBlock::Text(t) = c {
349	                                    Some(t.as_str())
350	                                } else {
351	                                    None
352	                                }
353	                            })
354	                            .unwrap_or("");
355	                        json!({
356	                            "toolResult": {
357	                                "toolUseId": tr.tool_use_id,
358	                                "content": [{"text": text_content}],
359	                            }
360	                        })
361	                    }
362	                    _ => json!({"unknown": true}),
363	                })
364	                .collect();
365	            json!({"role": role, "content": content})
366	        })
367	        .collect();
368	
369	    // Tool config
370	    let tool_config: Value = match &p.tool_config {
371	        None => Value::Null,
372	        Some(tc) => {
373	            let tools: Vec<Value> = tc
374	                .tools()
375	                .iter()
376	                .map(|t| match t {
377	                    Tool::ToolSpec(spec) => {
378	                        let schema_placeholder = match spec.input_schema() {
379	                            Some(s) if s.is_json() => json!("<Document>"),
380	                            _ => Value::Null,
381	                        };
382	                        json!({
383	                            "toolSpec": {
384	                                "name": spec.name(),
385	                                "description": spec.description(),
386	                                "inputSchema": {"json": schema_placeholder},
387	                            }
388	                        })
389	                    }
390	                    _ => json!({"unknown": true}),
391	                })
392	                .collect();
393	            let tc_value: Value = match tc.tool_choice() {
394	                None => Value::Null,
395	                Some(SdkToolChoice::Auto(_)) => json!({"auto": {}}),
396	                Some(SdkToolChoice::Any(_)) => json!({"any": {}}),
397	                Some(SdkToolChoice::Tool(s)) => json!({"tool": {"name": s.name()}}),
398	                _ => json!({"unknown": true}),
399	            };
400	            json!({
401	                "tools": tools,
402	                "toolChoice": tc_value,
403	            })
404	        }
405	    };
406	
407	    // Inference config
408	    let inference_config: Value = match &p.inference_config {
409	        None => Value::Null,
410	        Some(ic) => {
411	            let mut m = serde_json::Map::new();
412	            if let Some(t) = ic.temperature() {
413	                m.insert("temperature".into(), json!(t));
414	            }
415	            if let Some(p) = ic.top_p() {
416	                m.insert("topP".into(), json!(p));
417	            }
418	            if let Some(mt) = ic.max_tokens() {
419	                m.insert("maxTokens".into(), json!(mt));
