  1	//! [`BedrockModel`] — the Bedrock Converse API model handle.
  2	//!
  3	//! Wraps an `Arc<Config>` so that the model handle is `Clone + Send + Sync`
  4	//! and the `BoxStream` returned by `invoke` can be `'static + Send`.
  5	
  6	use std::sync::Arc;
  7	
  8	use async_stream::stream;
  9	use async_trait::async_trait;
 10	use futures_core::stream::BoxStream;
 11	use paigasus_helikon_core::{
 12	    CancellationToken, Model, ModelCapabilities, ModelError, ModelEvent, ModelRequest,
 13	};
 14	
 15	use crate::builder::Config;
 16	use crate::error::{map_sdk_error, map_sdk_http_error};
 17	use crate::stream::StreamTranslator;
 18	use crate::translate::build_request;
 19	
 20	// ── BedrockModel ──────────────────────────────────────────────────────────────
 21	
 22	/// An Amazon Bedrock Converse API model handle.
 23	///
 24	/// Construct via [`BedrockModel::converse`] (sync builder) or
 25	/// [`BedrockModel::from_env`] (async, loads AWS config from the environment).
 26	///
 27	/// The handle is `Clone + Send + Sync` because it holds only an `Arc<Config>`.
 28	#[derive(Debug, Clone)]
 29	pub struct BedrockModel(pub(crate) Arc<Config>);
 30	
 31	// ── Model impl ────────────────────────────────────────────────────────────────
 32	
 33	#[async_trait]
 34	impl Model for BedrockModel {
 35	    /// Stream model events from Amazon Bedrock's Converse API.
 36	    ///
 37	    /// The returned stream is `'static + Send`.
 38	    ///
 39	    /// **Cancellation contract:** when `cancel` fires mid-stream, the stream
 40	    /// ends immediately without emitting a final `Finish` event (per the core
 41	    /// `Model` trait contract).
 42	    async fn invoke(
 43	        &self,
 44	        request: ModelRequest,
 45	        cancel: CancellationToken,
 46	    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
 47	        // Translate the core request into Bedrock wire format (early error on
 48	        // translation failure — before we open any network connection).
 49	        let prepared = build_request(&self.0, &request)?;
 50	
 51	        let synthesizing = prepared.synthesizing;
 52	        let client = self.0.client.clone();
 53	
 54	        // Build the fluent ConverseStream request from the prepared parts.
 55	        let fluent = client
 56	            .converse_stream()
 57	            .model_id(&prepared.model_id)
 58	            .set_messages(Some(prepared.messages))
 59	            .set_system(if prepared.system.is_empty() {
 60	                None
 61	            } else {
 62	                Some(prepared.system)
 63	            })
 64	            .set_tool_config(prepared.tool_config)
 65	            .set_inference_config(prepared.inference_config);
 66	
 67	        let s = stream! {
 68	            // Send the ConverseStream request and obtain the event receiver.
 69	            // Guard with a cancellation check (biased: cancel arm wins) so that
 70	            // a token already fired — or one that fires during the HTTP send —
 71	            // aborts cleanly without opening a dangling Bedrock stream and
 72	            // without emitting Finish (per the Model::invoke cancellation contract).
 73	            let output = tokio::select! {
 74	                biased;
 75	                _ = cancel.cancelled() => { return; }
 76	                result = fluent.send() => {
 77	                    // map_sdk_http_error: fluent.send() returns
 78	                    // SdkError<_, HttpResponse>, so we can extract Retry-After headers.
 79	                    match result {
 80	                        Ok(o) => o,
 81	                        Err(e) => {
 82	                            yield Err(map_sdk_http_error(e));
 83	                            return;
 84	                        }
 85	                    }
 86	                }
 87	            };
 88	
 89	            let mut receiver = output.stream;
 90	            let mut translator = StreamTranslator::new(synthesizing);
 91	
 92	            loop {
 93	                let next = tokio::select! {
 94	                    biased;
 95	                    _ = cancel.cancelled() => {
 96	                        // Cancellation: end stream without emitting Finish.
 97	                        return;
 98	                    }
 99	                    r = receiver.recv() => r,
100	                };
101	
102	                match next {
103	                    // Stream exhausted normally (EOF).
104	                    // Flush any buffered stop reason that arrived without a
105	                    // subsequent Metadata event so the consumer always sees
106	                    // a terminal Finish.
107	                    Ok(None) => {
108	                        if let Some(terminal) = translator.finish() {
109	                            yield terminal;
110	                        }
111	                        return;
112	                    }
113	                    // Good event — feed through translator and yield results.
114	                    Ok(Some(event)) => {
115	                        for result in translator.consume(event) {
116	                            yield result;
117	                        }
118	                    }
119	                    // Transport-level error on the event stream.
120	                    Err(e) => {
121	                        yield Err(map_sdk_error(e));
122	                        return;
123	                    }
124	                }
125	            }
126	        };
127	
128	        Ok(Box::pin(s))
129	    }
130	
131	    fn capabilities(&self) -> ModelCapabilities {
132	        self.0.capabilities
133	    }
134	
135	    fn provider(&self) -> &str {
136	        "bedrock"
137	    }
138	
139	    fn model(&self) -> &str {
140	        &self.0.model_id
141	    }
142	}
