144	// ── Unit tests (descriptor + capability + cancellation contract) ──────────────
145	
146	#[cfg(test)]
147	mod tests {
148	    use super::*;
149	    use aws_config::{BehaviorVersion, Region};
150	    use futures_core::stream::BoxStream;
151	
152	    // ── Cancellation-wrapper helper (test-only) ───────────────────────────────
153	
154	    /// Wrap any `Stream<Item = Result<ModelEvent, ModelError>>` with a
155	    /// `CancellationToken` guard.
156	    ///
157	    /// When `cancel` fires, the returned stream ends immediately **without**
158	    /// emitting a `Finish` event — matching the `Model::invoke` cancellation
159	    /// contract.
160	    fn drive_stream_with_token<S>(
161	        source: S,
162	        cancel: CancellationToken,
163	    ) -> BoxStream<'static, Result<ModelEvent, ModelError>>
164	    where
165	        S: futures_core::Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static,
166	    {
167	        Box::pin(stream! {
168	            tokio::pin!(source);
169	            loop {
170	                let next = tokio::select! {
171	                    biased;
172	                    _ = cancel.cancelled() => return,
173	                    r = futures_util::StreamExt::next(&mut source) => r,
174	                };
175	                match next {
176	                    None => return,
177	                    Some(v) => yield v,
178	                }
179	            }
180	        })
181	    }
182	
183	    fn offline_model(model_id: &str) -> BedrockModel {
184	        let rt = tokio::runtime::Builder::new_current_thread()
185	            .enable_all()
186	            .build()
187	            .expect("tokio runtime");
188	        rt.block_on(async {
189	            let sdk_cfg = aws_config::defaults(BehaviorVersion::v2026_11_17())
190	                .region(Region::new("us-east-1"))
191	                .test_credentials()
192	                .load()
193	                .await;
194	            BedrockModel::converse(model_id)
195	                .sdk_config(&sdk_cfg)
196	                .build()
197	                .expect("build offline model")
198	        })
199	    }
200	
201	    // `offline_model` blocks on its own runtime, so this test is a plain
202	    // `#[test]` that drives `invoke` on a second runtime.
203	    #[test]
204	    fn invoke_rejects_blank_only_request_before_network() {
205	        let m = offline_model("anthropic.claude-3-5-sonnet-20241022-v2:0");
206	        let mut req = ModelRequest::new();
207	        req.messages = vec![paigasus_helikon_core::Item::UserMessage {
208	            content: vec![paigasus_helikon_core::ContentPart::Text {
209	                text: String::new(),
210	            }],
211	        }];
212	        let rt = tokio::runtime::Builder::new_current_thread()
213	            .enable_all()
214	            .build()
215	            .expect("tokio runtime");
216	        let res = rt.block_on(m.invoke(req, CancellationToken::new()));
217	        match res {
218	            Err(ModelError::Other(e)) => assert!(
219	                e.to_string().contains("no message with content to send"),
220	                "unexpected error: {e}"
221	            ),
222	            Err(e) => panic!("unexpected error variant: {e}"),
223	            Ok(_) => panic!("expected an error"),
224	        }
225	    }
226	
227	    #[test]
228	    fn provider_returns_bedrock() {
229	        let m = offline_model("anthropic.claude-3-5-sonnet-20241022-v2:0");
230	        assert_eq!(m.provider(), "bedrock");
231	    }
232	
233	    #[test]
234	    fn model_returns_configured_id() {
235	        let id = "anthropic.claude-3-5-sonnet-20241022-v2:0";
236	        let m = offline_model(id);
237	        assert_eq!(m.model(), id);
238	    }
239	
240	    #[test]
241	    fn capabilities_matches_caps_for_anthropic() {
242	        let m = offline_model("anthropic.claude-3-5-sonnet-20241022-v2:0");
243	        let caps = m.capabilities();
244	        assert!(caps.streaming);
245	        assert!(caps.tools);
246	        assert!(caps.structured_output);
247	        assert!(
248	            !caps.vision,
249	            "vision not advertised (no image-block mapping)"
250	        );
251	    }
252	
253	    #[test]
254	    fn model_is_clone() {
255	        let m = offline_model("amazon.nova-pro-v1:0");
256	        let m2 = m.clone();
257	        assert_eq!(m.model(), m2.model());
258	    }
259	
260	    // ── Cancellation contract tests ───────────────────────────────────────────
261	
262	    use futures_core::Stream;
263	    use futures_util::StreamExt;
264	
265	    /// Build a stream that yields `n` `TokenDelta` events then ends.
266	    fn token_stream(
267	        n: usize,
268	    ) -> impl Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static {
269	        let events: Vec<Result<ModelEvent, ModelError>> = (0..n)
270	            .map(|i| {
271	                Ok(ModelEvent::TokenDelta {
272	                    text: format!("chunk-{i}"),
273	                })
274	            })
275	            .collect();
276	        futures_util::stream::iter(events)
277	    }
278	
279	    /// Build a stream that yields `n` `TokenDelta` events then a `Finish` event.
280	    fn token_stream_with_finish(
281	        n: usize,
282	    ) -> impl Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static {
283	        use paigasus_helikon_core::FinishReason;
284	        let mut events: Vec<Result<ModelEvent, ModelError>> = (0..n)
285	            .map(|i| {
286	                Ok(ModelEvent::TokenDelta {
287	                    text: format!("chunk-{i}"),
288	                })
289	            })
290	            .collect();
291	        events.push(Ok(ModelEvent::Finish {
292	            reason: FinishReason::Stop,
293	        }));
294	        futures_util::stream::iter(events)
295	    }
296	
297	    #[tokio::test]
298	    async fn cancel_before_stream_ends_no_finish() {
299	        let cancel = CancellationToken::new();
300	        let source = token_stream(10);
301	
302	        // Cancel immediately — the stream should yield 0 events and no Finish.
303	        cancel.cancel();
304	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
305	
306	        let has_finish = events
307	            .iter()
308	            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
309	        assert!(!has_finish, "cancelled stream must not emit Finish");
310	    }
311	
312	    #[tokio::test]
313	    async fn cancel_mid_stream_no_finish() {
314	        use std::sync::atomic::{AtomicBool, Ordering};
315	        use std::sync::Arc;
316	
317	        let cancel = CancellationToken::new();
318	        let cancel_clone = cancel.clone();
319	
320	        // A stream that cancels itself after yielding the first token.
321	        let cancelled = Arc::new(AtomicBool::new(false));
322	        let cancelled_clone = cancelled.clone();
323	
324	        let source = async_stream::stream! {
325	            yield Ok::<ModelEvent, ModelError>(ModelEvent::TokenDelta { text: "first".to_owned() });
326	            // Signal cancellation after the first token.
327	            if !cancelled_clone.swap(true, Ordering::SeqCst) {
328	                cancel_clone.cancel();
329	            }
330	            // `biased;` in drive_stream_with_token's tokio::select! checks the
331	            // cancel arm first on every iteration, so once cancel() fires the
332	            // driver exits before polling the source again — making this
333	            // single-threaded ordering deterministic and guaranteeing no Finish
334	            // is emitted after cancel.
335	            yield Ok(ModelEvent::TokenDelta { text: "second".to_owned() });
336	            yield Ok(ModelEvent::Finish { reason: paigasus_helikon_core::FinishReason::Stop });
337	        };
338	
339	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
340	
341	        let has_finish = events
342	            .iter()
343	            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
344	        assert!(!has_finish, "mid-stream cancel must not emit Finish");
345	    }
346	
347	    #[tokio::test]
348	    async fn uncancelled_stream_emits_finish() {
349	        let cancel = CancellationToken::new();
350	        let source = token_stream_with_finish(3);
351	
352	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
353	
354	        let has_finish = events
355	            .iter()
356	            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
357	        assert!(has_finish, "uncancelled stream must emit Finish");
358	        // All 3 token deltas + finish = 4 events.
359	        assert_eq!(events.len(), 4, "expected 3 tokens + 1 finish");
360	    }
361	
362	    #[tokio::test]
363	    async fn cancel_does_not_drop_events_already_yielded() {
364	        let cancel = CancellationToken::new();
365	        // 5 events, no finish.  Don't cancel — all should arrive.
366	        let source = token_stream(5);
367	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
368	        assert_eq!(events.len(), 5, "all events must arrive when not cancelled");
369	    }
370	}

