    fn finish_events(&self, reason: StopReason) -> Vec<Result<ModelEvent, ModelError>> {
        let finish = match reason {
            StopReason::EndTurn | StopReason::StopSequence => Ok(ModelEvent::Finish {
                reason: FinishReason::Stop,
